                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <section id="backend" class="section-anchor mb-10" data-title="Integrasi Backend">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h2 class="text-xl font-black text-gray-800 mb-1 flex items-center gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <i class="fas fa-plug text-gray-600 text-lg">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </i>Integrasi Backend (<code>/api/notify</code>)</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="w-12 h-1 bg-gray-500 rounded-full mb-5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h4 class="font-black text-gray-800 text-sm mb-2">Helper Fungsi</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <pre class="kode mb-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span class="k">async function</span> callBackend(payload)       <span class="c">// POST lenient (error diabaikan)</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span class="k">async function</span> callBackendStrict(payload) <span class="c">// POST ketat (throw jika error)</span>
