                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <section id="faq" class="section-anchor mb-10" data-title="FAQ">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <h2 class="text-xl font-black text-gray-800 mb-1 flex items-center gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <i class="fas fa-question-circle text-gray-600 text-lg">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </i>FAQ</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="w-12 h-1 bg-gray-400 rounded-full mb-5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="space-y-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <details class="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <summary class="font-black text-gray-800 text-sm flex justify-between items-center gap-2">Lupa PIN siswa?<i class="fas fa-chevron-down text-gray-400 text-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p class="mt-3 text-xs text-gray-600">Klik <strong>"Lupa PIN?"</strong> → jawab pertanyaan keamanan → atur PIN baru. Admin juga bisa reset via <strong>Data Siswa → Edit → Reset PIN</strong>.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </details>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <details class="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <summary class="font-black text-gray-800 text-sm flex justify-between items-center gap-2">Tidak perlu isi tgl lahir lagi?<i class="fas fa-chevron-down text-gray-400 text-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p class="mt-3 text-xs text-gray-600">Benar. Setelah PIN di-set, login berikutnya cukup Nama + Kelas + PIN.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </details>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <details class="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <summary class="font-black text-gray-800 text-sm flex justify-between items-center gap-2">Login Portal Guru "Belum waktunya mata pelajaran"?<i class="fas fa-chevron-down text-gray-400 text-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p class="mt-3 text-xs text-gray-600">Portal Guru membatasi akses hanya saat <strong>mengajar</strong>. Cek banner jadwal. Admin bisa matikan pembatasan di <strong>Pengaturan Web → Portal Guru</strong>.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </details>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <details class="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <summary class="font-black text-gray-800 text-sm flex justify-between items-center gap-2">Bagaimana cara unduh QR massal?<i class="fas fa-chevron-down text-gray-400 text-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p class="mt-3 text-xs text-gray-600">Data Siswa → centang siswa (atau Pilih Semua) → Tindakan → <strong>Unduh QR</strong>. Bisa pilih siswa terpilih atau semua → hasil ZIP berisi PNG per siswa.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </details>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <details class="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <summary class="font-black text-gray-800 text-sm flex justify-between items-center gap-2">Gembok superadmin tidak bisa dibuka?<i class="fas fa-chevron-down text-gray-400 text-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p class="mt-3 text-xs text-gray-600">Klik ikon 🔒 <strong>3x berturut-turut</strong> (max jeda 1,5 detik antar klik) → masukkan PIN <code>2410</code>.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </details>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <details class="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <summary class="font-black text-gray-800 text-sm flex justify-between items-center gap-2">Apa itu aksi_v2 di role?<i class="fas fa-chevron-down text-gray-400 text-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p class="mt-3 text-xs text-gray-600">Penanda jabatan sudah memakai pembatasan tombol. Jabatan lama (tanpa penanda) tetap boleh semua tombol — tidak ada yang tiba-tiba terkunci. Edit &amp; simpan ulang untuk memakai pembatasan.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </details>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <details class="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <summary class="font-black text-gray-800 text-sm flex justify-between items-center gap-2">Mode Demo datanya hilang?<i class="fas fa-chevron-down text-gray-400 text-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p class="mt-3 text-xs text-gray-600">Benar. Mode demo menyimpan data di memori browser saja — hilang saat reload. Untuk data nyata, login dengan akun.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </details>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <details class="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <summary class="font-black text-gray-800 text-sm flex justify-between items-center gap-2">Restore database aman?<i class="fas fa-chevron-down text-gray-400 text-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p class="mt-3 text-xs text-gray-600">Ya. Sistem membuat <strong>backup pengaman otomatis</strong> sebelum restore, dan restore bersifat <strong>transactional</strong> (gagal di tengah = data lama utuh).</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </details>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <details class="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <summary class="font-black text-gray-800 text-sm flex justify-between items-center gap-2">Notifikasi WA tidak masuk?<i class="fas fa-chevron-down text-gray-400 text-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p class="mt-3 text-xs text-gray-600">Cek: (1) Token Fonnte terisi, (2) HP Fonnte online, (3) Nomor siswa terisi.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                </details>
                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        </section>
