/* ============================================================
   Sidebar navigation
   ============================================================ */
function goTo(id) {
  const el = document.getElementById(id);
  if (el) el.scrollIntoView({ behavior: 'smooth' });
  if (window.innerWidth < 768) toggleSidebar();
}

function toggleSidebar() {
  const s = document.getElementById('sidebar');
  const o = document.getElementById('sidebarOverlay');
  if (!s || !o) return;
  s.classList.toggle('hidden');
  o.classList.toggle('hidden');
}

/* Active link on scroll */
const links = document.querySelectorAll('#sidebarNav .sidebar-link');
const navLinks = document.querySelectorAll('.mobile-nav a[data-nav]');
window.addEventListener('scroll', () => {
  let current = '';
  document.querySelectorAll('.section-anchor[id]').forEach(s => {
    if (window.scrollY >= s.offsetTop - 90) current = s.id;
  });
  links.forEach(l => {
    const href = l.getAttribute('onclick')?.match(/'([^']+)'/)?.[1];
    l.classList.toggle('active', href === current);
  });
  navLinks.forEach(l => {
    const nav = l.getAttribute('data-nav');
    l.classList.toggle('active', nav === current);
  });
}, { passive: true });

/* ============================================================
   DOWNLOAD MODAL
   ============================================================ */
function bukaDownloadModal() {
  const list = document.getElementById('sectionDownloadList');
  list.innerHTML = SECTIONS.map(s => `
    <button onclick="downloadPDF('${s.id}')" class="w-full flex items-center gap-3 px-4 py-2.5 bg-gray-50 hover:bg-blue-50 border border-gray-100 hover:border-blue-200 rounded-xl transition active:scale-95 text-left">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="w-7 h-7 bg-white rounded-lg border border-gray-200 flex items-center justify-center flex-shrink-0 shadow-sm">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <i class="fas fa-file-pdf text-red-500 text-[11px]">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span class="font-bold text-gray-700 text-xs">${s.title}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <i class="fas fa-chevron-right ml-auto text-gray-300 text-[10px]">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>`).join('');
  document.getElementById('downloadModal').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}
function tutupDownloadModal() {
  document.getElementById('downloadModal').classList.add('hidden');
  document.body.style.overflow = '';
}
document.getElementById('downloadModal').addEventListener('click', e => { if (e.target === document.getElementById('downloadModal')) tutupDownloadModal(); });

/* ============================================================
   PDF DOWNLOAD
   ============================================================ */
async function downloadPDF(sectionId) {
  tutupDownloadModal();
  const { jsPDF } = window.jspdf;

  const toast = document.createElement('div');
  toast.id = 'pdfToast';
  toast.className = 'fixed bottom-6 left-1/2 -translate-x-1/2 bg-gray-900 text-white px-5 py-3 rounded-2xl text-sm font-bold flex items-center gap-3 z-[300] shadow-2xl';
  toast.innerHTML = '<i class="fas fa-circle-notch fa-spin text-blue-400">
                                                                                                                                                                                                                                                                                                                                                                                                                                                            </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span>Membuat PDF...</span>';
  document.body.appendChild(toast);

  try {
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const pageW = 210, pageH = 297, margin = 14;

    function addHeader(doc, title) {
      doc.setFillColor(37, 99, 235);
      doc.rect(0, 0, pageW, 22, 'F');
      doc.setTextColor(255,255,255);
      doc.setFontSize(9); doc.setFont('helvetica','bold');
      doc.text(String(window.NAMA_WEB||'E-ASPIRASI GRISAWANGI').toUpperCase(), margin, 9);
      doc.setFontSize(7); doc.setFont('helvetica','normal');
      doc.text('SMK PGRI 1 Giri — Dokumentasi Resmi v3.0', margin, 15);
      doc.setFontSize(8); doc.setFont('helvetica','bold');
      doc.text(title, pageW - margin, 12, { align: 'right' });
    }

    function addFooter(doc, pageNum, total) {
      doc.setFontSize(7); doc.setTextColor(148,163,184); doc.setFont('helvetica','normal');
      doc.text(`e-aspirasigrisawangi.my.id  ·  Halaman ${pageNum} dari ${total}`, pageW/2, pageH-6, { align: 'center' });
    }

    const targets = sectionId === 'all' ? SECTIONS : SECTIONS.filter(s => s.id === sectionId);

    let yPos = 30;
    let pageNum = 1;

    addHeader(doc, sectionId === 'all' ? 'Dokumentasi Lengkap' : (targets[0]?.title || ''));

    if (sectionId === 'all') {
      doc.setFillColor(37,99,235);
      doc.roundedRect(margin, 28, pageW - margin*2, 35, 4, 4, 'F');
      doc.setTextColor(255,255,255); doc.setFont('helvetica','bold'); doc.setFontSize(16);
      doc.text(String(window.NAMA_WEB||'E-Aspirasi Grisawangi'), pageW/2, 42, { align: 'center' });
      doc.setFont('helvetica','normal'); doc.setFontSize(9);
      doc.text('Dokumentasi Resmi v3.0 — SMK PGRI 1 Giri, Banyuwangi', pageW/2, 52, { align: 'center' });
      doc.setFontSize(8); doc.text('e-aspirasigrisawangi.my.id', pageW/2, 59, { align: 'center' });
      yPos = 75;
    }

    for (const sec of targets) {
      const el = document.getElementById(sec.id);
      if (!el) continue;

      if (yPos > pageH - 40) {
        addFooter(doc, pageNum, '?');
        doc.addPage(); pageNum++;
        addHeader(doc, sec.title);
        yPos = 30;
      }

      doc.setTextColor(37,99,235); doc.setFont('helvetica','bold'); doc.setFontSize(12);
      doc.text(sec.title, margin, yPos); yPos += 2;
      doc.setDrawColor(37,99,235); doc.setLineWidth(0.8);
      doc.line(margin, yPos, margin+20, yPos); yPos += 6;

      doc.setTextColor(51,65,85); doc.setFont('helvetica','normal'); doc.setFontSize(8);
      const textEl = el.querySelectorAll('p, li, h4, td');
      textEl.forEach(t => {
        if (yPos > pageH - 20) {
          addFooter(doc, pageNum, '?');
          doc.addPage(); pageNum++;
          addHeader(doc, sec.title);
          yPos = 30;
        }
        const tag = t.tagName.toLowerCase();
        const raw = t.textContent.replace(/\s+/g,' ').trim();
        if (!raw) return;
        if (tag === 'h4') {
          doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(30,41,59);
          doc.text(raw, margin, yPos, { maxWidth: pageW - margin*2 });
          yPos += 6;
          doc.setFont('helvetica','normal'); doc.setFontSize(8); doc.setTextColor(51,65,85);
        } else {
          const prefix = tag === 'li' ? '  • ' : '';
          const lines = doc.splitTextToSize(prefix + raw, pageW - margin*2 - 4);
          doc.text(lines, margin + (tag === 'li' ? 2 : 0), yPos);
          yPos += lines.length * 4.5;
        }
      });
      yPos += 8;
    }

    const totalPages = doc.internal.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      addFooter(doc, i, totalPages);
    }

    const filename = sectionId === 'all'
      ? 'E-Aspirasi_Dokumentasi_Lengkap_v3.pdf'
      : `E-Aspirasi_${(targets[0]?.title||sectionId).replace(/\s/g,'_')}.pdf`;
    doc.save(filename);

    toast.innerHTML = '<i class="fas fa-check-circle text-green-400">
                                                                                                                                                                                                                                                                                                                                                                                                                                                        </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span>PDF berhasil diunduh!</span>';
    setTimeout(() => toast.remove(), 2500);
  } catch(e) {
    toast.innerHTML = `<i class="fas fa-times-circle text-red-400">
                                                                                                                                                                                                                                                                                                                                                                                                                                                    </i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span>Gagal: ${e.message}</span>`;
    setTimeout(() => toast.remove(), 3000);
  }
}
</script>
